import {Social,api} from './social.js';
import {normalizeMix,arrangementPreset,tracks} from './mix.js';
import {arrangerHtml,suggestedInstruments} from './arranger.js';
import {vinyl,memoryColors,memoryTheme,themeStyle,validColor} from './art.js';
import {drawConstellation,orbitPosition} from './constellation.js';
import{compose,render,Player,wav,moods,styles,endings}from'./music.js';
const $=s=>document.querySelector(s),app=$('#app'),player=new Player(),KEY='recall-melody-v1',DRAFT=KEY+'-draft';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaults=()=>({id:crypto.randomUUID(),title:'',memoryColor:'#39c9ef',story:'',story2:'',name1:'',name2:'',mode:'solo',mood:'warm',mood2:'happy',style:'piano',ending:'soft',tempo:null,mix:normalizeMix(),instruments:{melody:false,harmony:true,bass:true,drums:false,piano:true,guitar:false,violin:false},variation:0,created:new Date().toISOString()});
let libraryKey=KEY,draftKey=DRAFT,currentAccount=null;let project=defaults(),step=0,view='home',buffers=null,score=null,busy=false,timer;let arrangeHistory=[];
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let library=read(KEY,[]);if(!Array.isArray(library))library=[];library=library.flatMap(p=>{try{return[normalize(p)]}catch{return[]}});
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('浏览器暂时无法保存，请导出作品备份');return false}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function count(){$('#count').textContent=library.length}count();
function stop(){player.stop();document.querySelectorAll('[data-demo]').forEach(b=>b.textContent='▶')}
function nav(v){social.stopPolling();if(v==='rooms'){social.hub();return}history.replaceState(null,'',location.pathname);stop();view=v;document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.nav===v));if(v==='home')home();if(v==='library')showLibrary();window.scrollTo({top:0,behavior:'smooth'})}
function home(){app.innerHTML=`<section class="hero new-hero"><div class="hero-copy"><div class="eyebrow">A LITTLE LIFE. A LITTLE MELODY.</div><div class="hero-chip"><span>♪</span> 给记忆，另一种存在的方式</div><h1>把舍不得的瞬间，<br>留在<span class="hero-gradient">旋律</span>里。</h1><p>你记得的海风，没说完的话，和那一天的心跳。<br>用几个简单的选择，把它们写成自己的音乐。</p><div class="hero-actions"><button class="primary" id="start">开始我的第一段旋律</button><button class="secondary" id="duo">${social.localOnly?'坐在一起，共同写':'邀请一个人，一起写'}</button></div><div class="hero-meta"><span>不懂乐理，也能创作</span><span>7 种风格 · 自由编曲</span></div></div><div class="hero-universe" aria-hidden="true"><div class="universe-halo"></div><svg class="hero-wave" viewBox="0 0 600 500"><defs><linearGradient id="ribbon"><stop stop-color="#2bc6e9" stop-opacity="0"/><stop offset=".5" stop-color="#77dded"/><stop offset="1" stop-color="#b7a7f5" stop-opacity="0"/></linearGradient></defs>${Array.from({length:7},(_,i)=>`<path d="M-30 ${280+i*12}Q100 ${70+i*9} 300 ${250+i*8}T650 ${190+i*14}" fill="none" stroke="url(#ribbon)" stroke-width="${i===3?2:1}" opacity="${i===3?.6:.2}"/>`).join('')}</svg><div class="floating-album album-back">${vinyl({title:'山野来信',story:'林间的风',memoryColor:'#71d5b0'})}<span>林间的风 / SIDE B</span></div><div class="floating-album album-front">${vinyl({title:'那天的海风',story:'夏天海边的夕阳',memoryColor:'#39c9ef'})}<span>那天的海风 / SIDE A</span></div><div class="orbit-quote"><span>♪</span><div>有些回忆，不只有画面。<small>NOW WRITING YOUR STORY</small></div></div><span class="universe-note n1">♫</span><span class="universe-note n2">♩</span><span class="universe-note n3">✧</span></div></section><div class="home-strip"><span>故事成为音符</span><i>✧</i><span>颜色收藏情绪</span><i>✧</i><span>${social.localOnly?'两个人，并肩合奏':'两个人，隔空合奏'}</span></div><section><div class="section-head"><div><h2>先听听，回忆的样子</h2><p>三段示例，给你的第一段旋律一点灵感。</p></div><span>A LITTLE INSPIRATION</span></div><div class="examples">${[['sea','≈','海边坐到天亮','温暖 · 舒缓钢琴',''],['summer','☀','放学后的那条路','快乐 · 轻快电子','sun'],['night','☾','写给晚一点的自己','平静 · 温柔氛围','night']].map(([id,icon,title,sub,cls])=>`<article class="example"><div class="cover ${cls}">${icon}</div><div><h3>${title}</h3><p>${sub}</p></div><button class="round" data-demo="${id}" aria-label="试听${title}">▶</button></article>`).join('')}</div></section><div class="bottom-note"><span><b>01</b> 说说你的故事</span><span><b>02</b> 选一份心情与声音</span><span><b>03</b> 收藏你的回忆旋律</span></div>`;$('#start').onclick=()=>start();$('#duo').onclick=()=>social.hub();document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>demo(b))}
function start(mode){const draft=read(draftKey,null);try{project=draft?normalize(draft):defaults()}catch{project=defaults()}if(mode&&mode!=='solo'&&!social.localOnly){social.hub(mode);return}project.mode=mode||'solo';step=0;view='editor';stop();editor();window.scrollTo(0,0)}
const option=(key,value,title,desc='',symbol='')=>`<button type="button" class="option ${project[key]===value?'selected':''}" data-key="${key}" data-value="${value}">${symbol?`<span class="symbol">${symbol}</span>`:''}${title}${desc?`<small>${desc}</small>`:''}</button>`;
function colorPicker(p=project,owner='project'){
 const t=memoryTheme(p);return `<div class="color-picker" data-owner="${owner}"><div class="color-heading"><span>这段回忆，是什么颜色？</span><span class="color-name">${t.name}</span></div><div class="color-swatches">${memoryColors.map(c=>`<button type="button" class="color-swatch ${t.hex===c.hex?'selected':''}" style="--swatch:${c.hex}" data-color="${c.hex}" data-owner="${owner}" aria-label="${c.name}：${c.word}" aria-pressed="${t.hex===c.hex}"><i></i><span>${c.name}</span></button>`).join('')}<label class="custom-swatch"><input type="color" value="${t.hex}" data-custom-color data-owner="${owner}" aria-label="自定义回忆颜色"><span>自选颜色</span></label></div><p class="color-help">选一个像它的颜色，让插画与唱片卡一起染上这份心情。</p></div>`
}
function wireColors(){
 const change=async(value,owner)=>{const color=validColor(value);if(owner!=='project'){const index=Number(owner);if(!library[index])return;const next=library.map((p,i)=>i===index?{...p,memoryColor:color}:p);if(persist(libraryKey,next)){library=next;showLibrary();document.querySelector(`.color-picker[data-owner="${index}"]`)?.closest('details')?.setAttribute('open','');if(social.user){try{await api('/projects','PUT',library[index])}catch(e){toast('换色已保存在本机：'+e.message)}}}return}
 project.memoryColor=color;if(view==='editor'){draft();editor()}else if(view==='result'){const card=$('.result-card');card.setAttribute('style',themeStyle(project));card.querySelector('.memory-vinyl').outerHTML=vinyl(project);card.querySelector('.color-picker').outerHTML=colorPicker();wireColors();const index=library.findIndex(p=>p.id===project.id);if(index>=0){const next=library.map((p,i)=>i===index?{...p,memoryColor:color}:p);if(persist(libraryKey,next)){library=next;if(social.user){try{await api('/projects','PUT',next[index])}catch(e){toast('换色已保存在本机：'+e.message)}}}}}
 };
 document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>change(b.dataset.color,b.dataset.owner));document.querySelectorAll('[data-custom-color]').forEach(el=>el.onchange=()=>change(el.value,el.dataset.owner))
}
function formContent(){switch(step){case 0:return`<div class="step-kicker">开始 · 选择模式</div><h2>这是谁的回忆？</h2><p class="hint">${social.localOnly?'独自收藏，或在同一台电脑上分别写下两个人的回忆。':'独自留住一段时光，或创建房间，邀请另一台设备上的 TA。'}</p><div class="options">${option('mode','solo','我的回忆','给自己，留住一个瞬间','♧')}${option('mode','couple','情侣回忆','用两个人的视角，写同一段故事','♡')}${option('mode','friends','朋友回忆','那些一起笑过、走过的日子','♬')}</div><p class="hint" style="margin-top:18px;margin-bottom:0">${social.localOnly?'情侣和朋友模式由两个人在这台电脑上分别填写，无需注册。':'情侣和朋友模式支持邀请链接：各自在自己的设备填写，双方提交后共同生成。'}</p>`;
case 1:return`<div class="step-kicker">故事 · 留住瞬间</div><h2>你想把哪段时光留下？</h2><p class="hint">不必写得完整。一个地点、一件小事，都可以是旋律的起点。</p><label class="field" for="title">给这段回忆起个名字</label><input id="title" type="text" maxlength="40" data-field="title" value="${escape(project.title)}" placeholder="例如：那天我们错过了末班车"><label class="field" for="story">${project.mode==='solo'?'发生了什么？':'第一位：你记得的那个瞬间'}</label><textarea id="story" data-field="story" maxlength="1200" placeholder="那天，海边的风很大，我们一直坐到了天亮……">${escape(project.story)}</textarea>${project.mode!=='solo'?`<label class="field" for="story2">把设备交给 TA：你又记得什么？</label><textarea id="story2" data-field="story2" maxlength="1200" placeholder="从你的视角，补上这段共同回忆。">${escape(project.story2)}</textarea>`:''}`;
case 2:return`<div class="step-kicker">心情 · 回忆的颜色</div><h2>想起它时，是什么感觉？</h2><p class="hint">${project.mode==='solo'?'选一种最接近此刻的心情。':'先由第一位选择心情，再请 TA 选择。两份心情会影响各自的音乐段落。'}</p><div class="options">${Object.entries(moods).map(([v,t])=>option('mood',v,t)).join('')}</div>${project.mode!=='solo'?`<label class="field">TA 的心情</label><div class="options">${Object.entries(moods).map(([v,t])=>option('mood2',v,t)).join('')}</div>`:''}`+colorPicker();
case 3:return`<div class="step-kicker">声音 · 选择听感</div><h2>它应该是什么声音？</h2><p class="hint">不用了解音乐流派，选一个你喜欢的氛围就好。</p><div class="options">${option('style','piano','舒缓钢琴','轻柔的键盘音色，适合慢慢想起','♮')}${option('style','electronic','轻快电子','明亮的合成音色，和有弹性的节奏','⌁')}${option('style','ambient','温柔氛围','稀疏的旋律，让回忆缓缓展开','☾')}${option('style','rnb','R&B 律动','切分低音、摇摆鼓点与柔和七和弦','♬')}${option('style','folk','民谣','木吉他分解和弦，像坐在身边讲故事','♧')}${option('style','ballad','抒情芭乐','钢琴铺陈与弦乐，让情绪慢慢舒展','♡')}${option('style','rock','摇滚','有力鼓点、强拍贝斯与电吉他感音色','ϟ')}</div><label class="field">想让哪些声音加入？</label><div class="checks">${instrumentChecks()}</div><p class="hint" style="margin-top:12px;margin-bottom:0">钢琴勾勒主题，吉他铺开拨弦，小提琴拉长情绪。选好后，还可以在播放中随时开关。</p>`;
case 4:return`<div class="step-kicker">结尾 · 留一点余韵</div><h2>想让这段回忆怎样落下？</h2><p class="hint">选择音乐从开始到结尾的情绪走向。</p><div class="options">${option('ending','soft','轻轻落下','音乐逐渐舒缓，像合上一本手账','☾')}${option('ending','rise','带着期待','能量慢慢增加，像走向下一站','☀')}${option('ending','steady','留在此刻','保留平稳的心情，让时光停一会儿','≈')}${option('ending','resolve','圆满落幕','用收束的乐句，为回忆画上一个句号','✧')}</div>`;
case 5:return`<div class="step-kicker">确认 · 准备聆听</div><h2>让这段回忆，成为旋律。</h2><p class="hint">这是我们一起选好的创作方向。你可以返回修改，也可以现在听见它。</p><div class="summary">${escape(summary())}</div><p class="hint" style="margin-top:20px">故事文字会形成这首作品的旋律种子；你选择的心情、风格和结尾决定编曲。双人作品依次呈现两人的主题，再交替合奏。</p>`}}
function summary(){return`《${project.title||'未命名的回忆'}》将以${styles[project.style]}呈现${moods[project.mood]}的心情${project.mode!=='solo'?`，加入另一位${moods[project.mood2]}的主题`:''}。${project.ending==='rise'?'从轻柔开始，逐渐积蓄力量。':project.ending==='soft'?'最后让音乐轻轻落下。':project.ending==='resolve'?'以圆满的终止乐句，为回忆收尾。':'保持平稳的节奏，留在这一刻。'} ${project.instruments.drums?'加入鼓点，':''}${project.instruments.bass?'以贝斯铺垫低音。':''}`}
function instrumentChecks(){return Object.entries({piano:'钢琴',guitar:'吉他',violin:'小提琴',bass:'贝斯',drums:'鼓点',melody:'电子旋律',harmony:'氛围和声'}).map(([k,t])=>`<label class="check"><input type="checkbox" data-track="${k}" ${project.instruments[k]?'checked':''}>${t}</label>`).join('')}
function editor(){app.innerHTML=`<section class="workspace"><div class="workspace-title"><div class="eyebrow">A SOUNDTRACK OF YOUR OWN</div><h1>把故事，慢慢谱成旋律</h1><div class="steps">${Array.from({length:6},(_,i)=>`<span class="${i<=step?'on':''}"></span>`).join('')}</div></div><div class="editor"><div class="form-card">${formContent()}<div class="form-actions"><button class="secondary" id="back">${step?'上一步':'返回首页'}</button><button class="primary" id="next">${step===5?'♫ 生成我的旋律':'继续'}</button></div></div><aside class="preview"><div class="preview-title">YOUR MEMORY · 创作手账</div>${vinyl(project)}<h3 id="previewTitle">${escape(project.title||'等待命名的回忆')}</h3><div class="tags"><span class="tag">${project.mode==='solo'?'独自收藏':project.mode==='couple'?'情侣回忆':'朋友回忆'}</span><span class="tag">${moods[project.mood]}</span><span class="tag">${styles[project.style]}</span></div><p>封面从你的回忆场景中生长，<br>让每一段旋律，都有自己的样子。</p><p>草稿自动保存在当前浏览器。</p></aside></div></section>`;
 document.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>{if(b.dataset.key==='mode'&&b.dataset.value!=='solo'&&!social.localOnly){social.hub(b.dataset.value);return}project[b.dataset.key]=b.dataset.value;if(b.dataset.key==='style'){project.instruments=suggestedInstruments(project.style);project.tempo=null;project.mix=normalizeMix()}draft();editor()});document.querySelectorAll('[data-field]').forEach(el=>el.oninput=()=>{project[el.dataset.field]=el.value;draft();if(el.id==='title')$('#previewTitle').textContent=el.value||'等待命名的回忆'});wireTracks();wireColors();$('#back').onclick=()=>{if(step){step--;editor()}else nav('home')};$('#next').onclick=()=>{if(step===1&&(!project.title.trim()||!project.story.trim()||(project.mode!=='solo'&&!project.story2.trim()))){toast('请填写回忆名称和每位参与者的故事');return}if(step===3&&!Object.values(project.instruments).some(Boolean)){toast('至少保留一种声音吧');return}if(step===5)generate();else{step++;editor();window.scrollTo(0,0)}}}
function draft(){persist(draftKey,project)}
function wireTracks(){document.querySelectorAll('[data-track]').forEach(el=>el.onchange=()=>{project.instruments[el.dataset.track]=el.checked;player.toggle(el.dataset.track,el.checked);if(view==='editor')draft();if(view==='result'&&$('#arranger-host')){updateArranger()}})}
async function generate(){if(busy)return;busy=true;stop();const b=$('#next');if(b){b.disabled=true;b.textContent='正在谱写旋律…'}try{const nextScore=compose(project),nextBuffers=await render(nextScore);score=nextScore;buffers=nextBuffers;arrangeHistory=[];player.setMix(project.mix);view='result';result();window.scrollTo(0,0)}catch(e){toast('音频生成未完成，请使用支持 Web Audio 的现代浏览器重试');console.error(e)}finally{busy=false;if(b?.isConnected){b.disabled=false;b.textContent='♫ 生成我的旋律'}}}
function result(){app.innerHTML=`<section class="result"><div class="workspace-title"><div class="eyebrow">THIS MOMENT, IN MELODY</div><p>你的回忆，已经有了声音。</p></div><div class="result-card" style="${themeStyle(project)}">${vinyl(project)}<div class="tags" style="justify-content:center"><span class="tag">${styles[project.style]}</span><span class="tag">${moods[project.mood]}</span><span class="tag">${score.bpm} BPM</span></div><h1>${escape(project.title)}</h1><div class="story">${escape(project.story)}${project.mode!=='solo'?`<br><br>TA 记得：${escape(project.story2)}`:''}</div><details class="result-colors"><summary>给回忆换一种颜色 <span>◉</span></summary>${colorPicker()}</details><div class="player-console constellation-player"><div class="player-topline"><span>MELODY CONSTELLATION</span><span id="play-status">READY TO LISTEN</span></div><div class="orbit-stage"><canvas id="constellation" role="slider" tabindex="0" aria-label="星轨播放进度，方向键调整，Home 回到开头" aria-valuemin="0" aria-valuemax="${Math.floor(score.duration)}" aria-valuenow="0"></canvas><div class="orbit-core"><button class="play-main" id="play" aria-label="播放旋律">▶</button><span class="orbit-core-label">LISTEN TO<br>YOUR MEMORY</span></div><span class="orbit-caption">让回忆，沿着旋律运行</span></div><input class="seek accessible-seek" id="seek" type="range" min="0" max="${score.duration}" value="0" step=".1" aria-label="播放进度"><div class="player-timeline"><span id="time">0:00</span><span class="orbit-tip">轻触星轨 · 跳转时光</span><span>${clock(score.duration)}</span></div><div class="memory-chapters">${['起笔','回响','展开','余韵'].map((name,i)=>`<button class="chapter" data-chapter="${i}"><span class="chapter-dot">${['♪','♩','♫','♬'][i]}</span><span>${name}</span></button>`).join('')}</div></div><div class="checks">${instrumentChecks()}</div><div class="volume"><span>音量</span><input id="volume" aria-label="播放音量" type="range" min="0" max="1" step=".01" value="${player.volume}"></div><div id="arranger-host">${arrangerHtml(project,score)}</div><div class="tools"><button class="primary" id="save">收藏这段回忆</button><button class="secondary" id="audio">下载音频</button><button class="secondary" id="export">备份作品</button></div><div class="tools"><button class="text-btn" id="edit">修改创作方向</button><button class="text-btn" id="variation">再谱一个版本</button><button class="text-btn" id="new">创作下一段</button><button class="text-btn" data-share-site>邀请朋友创作</button></div><p class="result-note">声音由此设备合成。作品备份可导入并还原旋律；音频下载为 WAV 格式。</p></div></section>`;wireTracks();wireColors();wireOrbit();wireArranger();$('#play').onclick=async()=>{try{if(player.playing){player.pause();$('#play').textContent='▶';$('#play').setAttribute('aria-label','播放旋律')}else{await player.play(buffers,project.instruments,project.mix);$('#play').textContent='Ⅱ';$('#play').setAttribute('aria-label','暂停播放')}}catch{toast('无法播放，请检查浏览器音频权限')}};$('#seek').onchange=async e=>{try{await player.seek(Number(e.target.value),buffers,project.instruments)}catch{toast('跳转未完成，请重新播放')}};$('#volume').oninput=e=>player.setVolume(Number(e.target.value));$('#save').onclick=save;$('#export').onclick=()=>download(JSON.stringify({format:'recall-melody',version:1,project},null,2),'json','application/json');$('#audio').onclick=()=>download(wav(buffers,project.instruments,project.mix),'wav');$('#edit').onclick=()=>{stop();view='editor';step=3;editor()};$('#variation').onclick=async()=>{project={...project,id:crypto.randomUUID(),variation:project.variation+1,created:new Date().toISOString()};$('#variation').disabled=true;await generate()};document.querySelectorAll('[data-share-site]').forEach(b=>b.onclick=shareWebsite);$('#new').onclick=()=>{stop();project=defaults();draft();start()}}
function arrangementSnapshot(){return {mix:JSON.parse(JSON.stringify(project.mix)),tempo:project.tempo}}
function rememberArrangement(snapshot=arrangementSnapshot()){arrangeHistory.push(snapshot);if(arrangeHistory.length>30)arrangeHistory.shift();const undo=$('#undo-arrange');if(undo)undo.disabled=false}
function updateArranger(){const host=$('#arranger-host');if(!host)return;host.innerHTML=arrangerHtml(project,score);wireArranger()}
function syncLane(k){const lane=document.querySelector(`[data-lane="${k}"]`),m=project.mix[k];if(!lane)return;lane.querySelector('[data-volume-label]').textContent=Math.round(m.volume*100)+'%';lane.querySelectorAll('[data-segment]').forEach(row=>{const segment=m.segments[Number(row.dataset.segment)];if(!segment)return;row.querySelector('.window-rail').style.cssText=`--from:${segment.start*100}%;--to:${segment.end*100}%`;row.querySelector('[data-window-label]').textContent=`${(segment.start*score.duration).toFixed(1)}s — ${(segment.end*score.duration).toFixed(1)}s`;row.querySelectorAll('[data-mix]').forEach(el=>el.value=Math.round(segment[el.dataset.mix]*100))});lane.querySelector('[data-mix="volume"]').value=Math.round(m.volume*100);lane.querySelector('.segment-overview').innerHTML=m.segments.map(seg=>`<i style="left:${seg.start*100}%;width:${(seg.end-seg.start)*100}%"></i>`).join('')}
async function applyTempo(tempo,wasUndo=false){if(busy)return;busy=true;const before=arrangementSnapshot(),scroll=window.scrollY,fraction=player.time/score.duration,resume=player.playing,b=$('#apply-tempo');if(b){b.disabled=true;b.textContent='重新演奏中…'}stop();try{const candidate={...project,tempo},next=compose(candidate),audio=await render(next,(done,total)=>{if(b?.isConnected)b.textContent=`重新演奏 ${done}/${total}…`});if(!wasUndo)rememberArrangement(before);project.tempo=tempo;score=next;buffers=audio;player.position=Math.min(fraction*score.duration,score.duration-.1);player.setMix(project.mix);result();window.scrollTo(0,scroll);if(resume)await player.play(buffers,project.instruments,project.mix);toast('速度已更新，音高保持不变')}catch(e){console.error(e);toast('速度调整未完成，请重试')}finally{busy=false;if(b?.isConnected){b.disabled=false;b.textContent='应用速度'}}}
function wireArranger(){
 $('#tempo').oninput=e=>$('#tempo-value').textContent=e.target.value+' BPM';$('#apply-tempo').onclick=()=>applyTempo(Number($('#tempo').value));
 document.querySelectorAll('[data-track-mix]').forEach(el=>{let before;const capture=()=>{before=arrangementSnapshot()};el.onfocus=capture;el.onpointerdown=capture;el.oninput=()=>{const k=el.dataset.trackMix,field=el.dataset.mix,v=Number(el.value)/100,m=project.mix[k];if(field==='volume')m.volume=v;else{const i=Number(el.dataset.segmentIndex),segment=m.segments[i],previous=m.segments[i-1],next=m.segments[i+1];if(field==='start')segment.start=Math.max(previous?previous.end+.01:0,Math.min(v,segment.end-.01));else segment.end=Math.min(next?next.start-.01:1,Math.max(v,segment.start+.01))}project.mix=normalizeMix(project.mix);player.setMix(project.mix);syncLane(k)};el.onchange=()=>{if(before)rememberArrangement(before);before=arrangementSnapshot()}});
 document.querySelectorAll('[data-add-segment]').forEach(b=>b.onclick=()=>{const k=b.dataset.addSegment,m=project.mix[k];if(m.segments.length>=16){toast('每种乐器最多 16 个片段');return}let cursor=0,gap=null;for(const seg of [...m.segments,{start:1,end:1}]){if(seg.start-cursor>=.04){gap={start:cursor,end:Math.min(seg.start-.01,cursor+.18)};break}cursor=seg.end+.01}if(!gap){toast('当前已占满时间轴，请先缩短或拆分已有片段');return}rememberArrangement();m.segments.push(gap);project.mix=normalizeMix(project.mix);player.setMix(project.mix);updateArranger()});
 document.querySelectorAll('[data-split-segment]').forEach(b=>b.onclick=()=>{const [k,index]=b.dataset.splitSegment.split(':'),m=project.mix[k],i=Number(index),seg=m.segments[i];if(m.segments.length>=16||seg.end-seg.start<.08){toast('片段太短或已达到数量上限');return}rememberArrangement();const middle=(seg.start+seg.end)/2;m.segments.splice(i,1,{start:seg.start,end:middle-.015},{start:middle+.015,end:seg.end});project.mix=normalizeMix(project.mix);player.setMix(project.mix);updateArranger()});
 document.querySelectorAll('[data-delete-segment]').forEach(b=>b.onclick=()=>{const [k,index]=b.dataset.deleteSegment.split(':');if(project.mix[k].segments.length<=1){toast('至少保留一个片段，或在上方关闭此乐器');return}rememberArrangement();project.mix[k].segments.splice(Number(index),1);project.mix=normalizeMix(project.mix);player.setMix(project.mix);updateArranger()});
 document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{rememberArrangement();project.mix=arrangementPreset(b.dataset.preset,project.instruments);player.setMix(project.mix);updateArranger();toast(b.dataset.preset==='dialogue'?'钢琴先叙述，吉他接话，弦乐在结尾相遇；可在上方启用这些乐器':'编曲已更新，点击播放听听变化')});
 document.querySelectorAll('[data-spotlight]').forEach(b=>b.onclick=()=>{rememberArrangement();const k=b.dataset.spotlight,t=Math.min(.9,player.time/score.duration),m=project.mix[k];m.start=Math.max(0,t-.08);m.end=Math.min(1,t+.18);m.segments=[{start:m.start,end:m.end}];m.volume=1.2;player.setMix(project.mix);updateArranger();toast(`${tracks[k]}的高光已放在 ${(t*score.duration).toFixed(1)} 秒附近`)});
 $('#reset-arrange').onclick=()=>{rememberArrangement();project.mix=normalizeMix();player.setMix(project.mix);updateArranger();toast('已恢复所有乐器整段演奏')};$('#save-arrange').onclick=save;$('#undo-arrange').disabled=!arrangeHistory.length;$('#undo-arrange').onclick=async()=>{const previous=arrangeHistory.pop();if(!previous)return;const tempoChanged=previous.tempo!==project.tempo;project.mix=previous.mix;player.setMix(project.mix);if(tempoChanged)await applyTempo(previous.tempo,true);else updateArranger();toast('已撤回上一次编曲调整')}
}
function shareWebsite(){const dialog=$('#share-dialog'),url=location.origin+location.pathname;if(social.localOnly){dialog.querySelector('h2').textContent='把这个音乐小屋，装进文件夹。';dialog.querySelector('p').textContent='把完整的「回忆成调-Windows版.zip」发给朋友。对方解压后双击「启动网页.cmd」，就能在自己的电脑上创作。';dialog.querySelector('label').textContent='想分享某一段旋律？请在作品页选择「下载音频」或「备份作品」，把导出的文件发给对方。127.0.0.1 是本机地址，复制它不能让别人访问。';$('#share-url').hidden=true;$('#copy-site').hidden=true;$('#native-share').hidden=true;dialog.showModal();return}$('#share-url').value=url;dialog.showModal();$('#copy-site').onclick=async()=>{try{await navigator.clipboard.writeText(url);toast('网页链接已复制，可以发给朋友')}catch{$('#share-url').select();toast('请复制选中的网址')}};$('#native-share').hidden=!navigator.share;$('#native-share').onclick=async()=>{try{await navigator.share({title:'回忆成调',text:'把一段回忆，变成自己的旋律。',url})}catch(e){if(e.name!=='AbortError')toast('请复制网页链接分享')}}}
function wireOrbit(){
 const canvas=$('#constellation');let dragging=false,resume=false;
 const seek=async value=>{try{await player.seek(value,buffers,project.instruments)}catch{toast('跳转未完成，请重新播放')}};
 const move=e=>{if(dragging)seek(orbitPosition(e.clientX,e.clientY,canvas.getBoundingClientRect(),score.duration))};
 canvas.onpointerdown=e=>{resume=player.playing;if(resume)player.pause();dragging=true;canvas.setPointerCapture(e.pointerId);move(e)};canvas.onpointermove=move;canvas.onpointerup=canvas.onpointercancel=async()=>{dragging=false;if(resume){resume=false;try{await player.play(buffers,project.instruments,project.mix)}catch{toast('无法继续播放，请重试')}}};
 canvas.onkeydown=e=>{let value;if(['ArrowRight','ArrowUp'].includes(e.key))value=player.time+1;if(['ArrowLeft','ArrowDown'].includes(e.key))value=player.time-1;if(e.key==='Home')value=0;if(e.key==='End')value=score.duration-.1;if(value!==undefined){e.preventDefault();seek(value)}};
 document.querySelectorAll('[data-chapter]').forEach(b=>b.onclick=()=>seek(Number(b.dataset.chapter)/4*score.duration));
}
function clock(t){return Math.floor(t/60)+':'+String(Math.floor(t%60)).padStart(2,'0')}
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');let lastFrame=0;
function animatePlayer(now){
 if(now-lastFrame>32&&view==='result'&&score&&$('#time')){
  lastFrame=now;let t=player.time;if(player.playing&&t>=score.duration){stop();t=0;$('#play').textContent='▶';$('#play').setAttribute('aria-label','播放旋律')}
  const progress=Math.min(1,t/score.duration);$('#play').textContent=player.playing?'Ⅱ':'▶';$('#play').setAttribute('aria-label',player.playing?'暂停播放':'播放旋律');$('#time').textContent=clock(Math.min(t,score.duration));if(document.activeElement!==$('#seek'))$('#seek').value=t;
  $('.result-card').classList.toggle('is-playing',player.playing);$('#play-status').textContent=player.playing?'NOW PLAYING':t>0?'PAUSED':'READY TO LISTEN';
  const canvas=$('#constellation');canvas.setAttribute('aria-valuenow',Math.floor(t));canvas.setAttribute('aria-valuetext',`${clock(t)}，共 ${clock(score.duration)}`);
  drawConstellation(canvas,{levels:player.frequencies(),progress,time:now/1000,playing:player.playing,color:validColor(project.memoryColor),reduced:reducedMotion.matches});
  document.querySelectorAll('[data-chapter]').forEach((el,i)=>el.classList.toggle('active',i<=Math.floor(progress*4)))
 }
 requestAnimationFrame(animatePlayer)
}requestAnimationFrame(animatePlayer);

async function save(){if(busy){toast('请等待当前演奏准备完成，再保存编曲');return}const existing=library.findIndex(p=>p.id===project.id),copy=JSON.parse(JSON.stringify(project));const next=[...library];if(existing>=0)next[existing]=copy;else next.unshift(copy);if(persist(libraryKey,next)){library=next;count();toast('已收藏到「我的回忆」');if(social.user){try{await api('/projects','PUT',copy);toast(social.localOnly?'已保存到此电脑的本机账户':'编曲已保存，并同步到你的账号')}catch(e){toast((social.localOnly?'浏览器已保存，本机账户保存未完成：':'已保存在本机，云端同步未完成：')+e.message)}}}}
function download(data,ext,type){const blob=data instanceof Blob?data:new Blob([data],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(project.title||'回忆成调').replace(/[\\/:*?"<>|]/g,'_')+'.'+ext;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function showLibrary(){app.innerHTML=`<section class="workspace"><div class="library-head"><div><div class="eyebrow">YOUR LITTLE ARCHIVE</div><h1>把时光，收藏在这里。</h1><p class="hint">${social.localOnly?(social.user?'已登录本机账户：作品保存在此电脑的数据库中；换电脑请导出作品。':'收藏保存在当前浏览器；可备份作品并在另一台电脑导入。'):(social.user?'已登录：收藏同步到账号，可在其他设备打开。':'访客收藏保存在当前浏览器；登录后保存的作品可跨设备同步。')}</p></div><button class="primary" id="create">新建回忆</button></div>${library.length?`<div class="saved-grid">${library.map((p,i)=>`<article class="saved" style="${themeStyle(p)}"><div class="saved-record">${vinyl(p)}<span class="record-caption">ORIGINAL MEMORY / ${String(i+1).padStart(2,'0')}</span></div><h3>${escape(p.title)}</h3><p>${moods[p.mood]||'温暖'} · ${styles[p.style]||'舒缓钢琴'}<br>${escape(new Date(p.created).toLocaleDateString('zh-CN'))}</p><details class="library-colors"><summary>回忆的颜色 <span>◉</span></summary>${colorPicker(p,String(i))}</details><div class="saved-actions"><button class="secondary" data-open="${i}">打开作品</button><button class="text-btn" data-delete="${i}">删除</button></div></article>`).join('')}</div>`:'<div class="empty"><p style="font-size:38px;color:#dba28f">♬</p><p>这里还很安静，等你的第一段回忆。</p></div>'}</section>`;wireColors();$('#create').onclick=()=>{project=defaults();draft();start()};document.querySelectorAll('[data-open]').forEach(b=>b.onclick=async()=>{if(busy)return;project=normalize(library[Number(b.dataset.open)]);b.disabled=true;b.textContent='正在还原…';await generate();if(b.isConnected){b.disabled=false;b.textContent='打开作品'}});document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=async()=>{if(!confirm(social.user?'从账号和本机收藏中删除此作品？已导出的备份不受影响。':'删除这段本地回忆？已导出的备份不受影响。'))return;const target=library[Number(b.dataset.delete)];if(social.user){try{await api('/projects/'+encodeURIComponent(target.id),'DELETE')}catch(e){toast(e.message);return}}const next=library.filter((_,i)=>i!==Number(b.dataset.delete));if(persist(libraryKey,next)){library=next;count();showLibrary()}})}
function normalize(p){if(!p||typeof p!=='object'||!['solo','couple','friends'].includes(p.mode)||!Object.hasOwn(moods,p.mood)||!Object.hasOwn(styles,p.style)||typeof p.story!=='string')throw Error('invalid');const d=defaults();for(const k of ['title','story','story2'])d[k]=typeof p[k]==='string'?p[k].slice(0,k==='title'?40:1200):'';d.memoryColor=validColor(p.memoryColor);d.id=typeof p.id==='string'?p.id.slice(0,80):d.id;d.mode=p.mode;d.mood=p.mood;d.mood2=Object.hasOwn(moods,p.mood2)?p.mood2:'warm';d.style=p.style;d.ending=Object.hasOwn(endings,p.ending)?p.ending:'soft';d.mix=normalizeMix(p.mix);d.tempo=typeof p.tempo==='number'&&Number.isFinite(p.tempo)?Math.max(60,Math.min(150,Math.round(p.tempo))):null;d.variation=Number.isInteger(p.variation)?Math.max(0,Math.min(10000,p.variation)):0;d.created=typeof p.created==='string'&&!isNaN(Date.parse(p.created))?p.created:d.created;for(const k of Object.keys(d.instruments))d.instruments[k]=typeof p.instruments?.[k]==='boolean'?p.instruments[k]:['piano','guitar','violin'].includes(k)?false:k==='melody'?true:d.instruments[k];return d}
$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>100000)throw Error();const data=JSON.parse(await f.text());if(data.format!=='recall-melody'||data.version!==1)throw Error();const imported=normalize(data.project);if(busy){toast('请等待当前旋律完成后再导入');return}project=imported;await generate();toast('作品已导入，可以试听并收藏')}catch{toast('无法导入，请选择本项目导出的有效 JSON 备份')}finally{e.target.value=''}};
async function demo(b){if(busy)return;if(player.playing){stop();return}busy=true;b.disabled=true;b.textContent='…';const p=defaults();p.story=b.dataset.demo;p.style=p.story==='summer'?'electronic':p.story==='night'?'ambient':'piano';p.mood=p.story==='summer'?'happy':p.story==='night'?'calm':'warm';p.instruments.drums=p.style==='electronic';p.instruments.melody=p.style==='electronic';p.instruments.piano=p.style!=='electronic';p.instruments.guitar=p.story==='sea';try{const s=compose(p),buf=await render(s);if(view==='home'){await player.play(buf,p.instruments);b.textContent='■';setTimeout(()=>{if(b.isConnected){stop();b.textContent='▶'}},10000)}}catch{toast('暂时无法试听，请检查浏览器音频支持')}finally{busy=false;b.disabled=false;if(b.textContent==='…')b.textContent='▶'}}
const social=new Social({root:app,toast,onView:()=>{stop();view='rooms';document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav==='rooms'))},onLocalStart:mode=>start(mode),onProject:async p=>{project=normalize(p);await generate()},onAccount:async user=>{const previous=currentAccount;currentAccount=user?.id||null;libraryKey=user?KEY+':'+user.id:KEY;draftKey=user?DRAFT+':'+user.id:DRAFT;let records=read(libraryKey,[]);if(user){try{records=(await api('/projects')).projects;persist(libraryKey,records)}catch(e){toast(e.message)}}library=(Array.isArray(records)?records:[]).flatMap(p=>{try{return[normalize(p)]}catch{return[]}});count();if(view==='library')showLibrary();if(!user&&previous){project=defaults();nav('home')}}});
document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>nav(b.dataset.nav));$('.brand').onclick=e=>{e.preventDefault();nav('home')};$('#share-site').onclick=shareWebsite;$('#close-share').onclick=()=>$('#share-dialog').close();home();social.init().then(()=>{if(view==='home')home()});
